<?php include 'includes/config.php'; $msg=''; if(isset($_POST['register'])){$name=$_POST['fullname'];$email=$_POST['email'];$hash=password_hash($_POST['password'],PASSWORD_DEFAULT);$stmt=mysqli_prepare($conn,"INSERT INTO users(fullname,email,password,role) VALUES(?,?,?,'user')");mysqli_stmt_bind_param($stmt,'sss',$name,$email,$hash); if(mysqli_stmt_execute($stmt)){$msg='Register berhasil, silakan login.';}else{$msg='Email sudah digunakan.';}} ?>
